async function collectTeam(date,signal,selectedAgents=null){const version=teamVersion;let roster;if(selectedAgents)roster={agents:selectedAgents};else{const response=await fetch('/api/agents?'+new URLSearchParams({date}),{signal});roster=await response.json();if(!response.ok)throw new Error(roster.error||'Could not load agents.');}const report=[];for(const [index,agent] of roster.agents.entries()){$('report-status').textContent='Loading '+(index+1)+' of '+roster.agents.length+' agents: '+agent.name;const response=await fetch('/api/recordings?'+new URLSearchParams({u:agent.username,q:date}),{signal});const data=await response.json();if(!response.ok||!Array.isArray(data.recordings))throw new Error('Could not load '+agent.name+'. '+(data.error||'No report was downloaded.'));report.push({...agent,recordings:data.recordings});}if(version===teamVersion)teamData={date,agents:report};return report;}
