function hours(seconds){if(seconds===null||seconds===undefined)return 'Unavailable';const n=Math.round(seconds);return Math.floor(n/3600)+':'+String(Math.floor(n%3600/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
