function cutoffDates(start,end){if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!/^\d{4}-\d{2}-\d{2}$/.test(end))throw new Error('Choose valid cutoff dates.');const first=Date.parse(start+'T00:00:00Z'),last=Date.parse(end+'T00:00:00Z');if(!Number.isFinite(first)||!Number.isFinite(last)||new Date(first).toISOString().slice(0,10)!==start||new Date(last).toISOString().slice(0,10)!==end||last<first)throw new Error('Cutoff end must be on or after the start.');if((last-first)/86400000>=31)throw new Error('Select a cutoff of up to 31 days.');return Array.from({length:(last-first)/86400000+1},(_,n)=>new Date(first+n*86400000).toISOString().slice(0,10));}
function mergeCutoff(days){const result={calls:0,callSeconds:0,sessionSeconds:0,rows:0,truncated:false,totals:{talk:0,wait:0,dispo:0,pause:0,dead:0},pauses:[],statuses:[]};const pauses=new Map(),statuses=new Map();for(const day of days){for(const key of ['calls','callSeconds','sessionSeconds'])result[key]=result[key]===null||day[key]===null?null:result[key]+day[key];result.rows+=day.rows;result.truncated ||= day.truncated;if(!day.totals)result.totals=null;else if(result.totals)for(const key of Object.keys(result.totals))result.totals[key]+=day.totals[key];for(const p of day.pauses){const key=p.campaign+'|'+p.code,old=pauses.get(key)||{...p,seconds:0,entries:0};old.seconds+=p.seconds;old.entries+=p.entries;pauses.set(key,old);}for(const s of day.statuses){const old=statuses.get(s.status)||{...s,calls:0,seconds:0};old.calls+=s.calls;old.seconds=old.seconds===null||s.seconds===null?null:old.seconds+s.seconds;statuses.set(s.status,old);}}result.pauses=[...pauses.values()].sort((a,b)=>b.seconds-a.seconds);result.statuses=[...statuses.values()];return result;}
function payrollCutoff(day,rule){const lastLogout=(day.loginEvents||[]).filter(e=>e.event==='LOGOUT'&&e.time.startsWith(day.date+' ')).map(e=>e.time).sort().at(-1)||null;const shiftEnd=rule.shiftEnds?.[day.date]||rule.shiftEnd||'18:30';if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(shiftEnd))throw Error(day.date+': enter a valid shift end.');if(!rule.cutoff)return {afterCutoff:0,lastLogout,shiftEnd,finishCallPaid:0};if(!Array.isArray(day.timeline))throw Error(day.date+': reload activity to apply the Eastern shift cutoff.');let afterCutoff=0,finishCallPaid=0;const boundary=Date.parse(day.date+'T'+shiftEnd+':00Z');for(const entry of day.timeline){if(!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(entry.time))throw Error(day.date+': activity timestamp unavailable for payroll cutoff.');let cursor=Date.parse(entry.time.replace(' ','T')+'Z');if(!Number.isFinite(cursor))throw Error(day.date+': invalid activity interval.');for(const category of ['pause','wait','talk','dispo']){const seconds=entry[category];if(!Number.isFinite(seconds)||seconds<0)throw Error(day.date+': invalid activity duration.');const end=cursor+seconds*1000;if(category!=='pause'&&rule[category]!==false){const late=Math.max(0,(end-Math.max(cursor,boundary))/1000);if(rule.finishCall&&category==='talk'&&cursor<boundary&&end>boundary)finishCallPaid+=late;else afterCutoff+=late;}cursor=end;}}return {afterCutoff,lastLogout,shiftEnd,finishCallPaid};}
function payrollAmounts(days,rate,lunchMinutes=0,adjustments={},rule={}){if(!Number.isFinite(lunchMinutes)||lunchMinutes<0||lunchMinutes>240)throw new Error('Lunch minimum must be between 0 and 240 minutes.');if(!Number.isFinite(rate)||rate<0||rate>100000)throw new Error('Enter a valid hourly rate.');if(days.some(d=>!d.totals||d.truncated))throw new Error('Payslip unavailable: activity data is missing or incomplete.');const rows=days.map(d=>{const cutoff=payrollCutoff(d,rule);const baseSeconds=(rule.talk===false?0:d.totals.talk)+(rule.wait===false?0:d.totals.wait)+(rule.dispo===false?0:d.totals.dispo);const recordedLunch=d.pauses.filter(p=>p.campaign==='INS'&&p.code==='6').reduce((sum,p)=>sum+p.seconds,0);const lunch=baseSeconds>0||recordedLunch>0?Math.max(recordedLunch,lunchMinutes*60):recordedLunch;const deduction=rule.lunch===false?0:Math.min(baseSeconds,Math.max(0,lunch-recordedLunch));const correction=adjustments[d.date]||{},minutes=Number(correction.minutes||0);if(!Number.isFinite(minutes)||minutes<0||minutes>1440)throw new Error(d.date+': enter 0–1,440 unpaid break minutes.');const manualDeduction=rule.manual===false?0:Math.round(minutes*60);if(manualDeduction>baseSeconds-deduction)throw new Error(d.date+': unpaid break exceeds remaining billable hours.');if(cutoff.afterCutoff>baseSeconds-deduction-manualDeduction)throw Error(d.date+': combined deductions exceed paid activity.');const seconds=baseSeconds-deduction-manualDeduction-cutoff.afterCutoff;return {seconds,...cutoff,manualDeduction,baseSeconds,recordedLunch,lunch,deduction,cents:Math.round(seconds*rate/3600*100)};});return {rows,seconds:rows.reduce((n,r)=>n+r.seconds,0),cents:rows.reduce((n,r)=>n+r.cents,0)};}
function restorePayroll(){try{const config=JSON.parse(localStorage.getItem('qa-payroll')||'{}');$('pay-lunch').value=config.lunchMinutes??60;setPayrollRule({...config.rule,cutoff:config.rule?.cutoff??true,finishCall:config.rule?.finishCall??true,lunch:config.rule?.lunch??false});$('pay-company').value=config.company||'AIG';$('pay-currency').value=config.currencies?.[$('activity-agent').value]||'USD';$('pay-rate').value=config.rates?.[$('activity-agent').value]??'';}catch{}}
function rememberPayroll(){try{const config=JSON.parse(localStorage.getItem('qa-payroll')||'{}');config.rule=getPayrollRule();config.lunchMinutes=Number($('pay-lunch').value);config.company=$('pay-company').value;config.currencies ||= {};config.currencies[$('activity-agent').value]=$('pay-currency').value;config.rates ||= {};if($('pay-rate').value!=='')config.rates[$('activity-agent').value]=$('pay-rate').value;localStorage.setItem('qa-payroll',JSON.stringify(config));}catch{}}
function renderPayslip(){if(!cutoffData)return;const c=cutoffData;const rate=Number($('pay-rate').value),currency=$('pay-currency').value;const money=cents=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(cents/100);$('pay-print').disabled=true;$('pay-save').disabled=true;$('slip-company').textContent=$('pay-company').value||'Company';$('slip-details').textContent=(c.name==='Choose an agent'?c.agent:c.name)+' ('+c.agent+') · '+c.start+' to '+c.end+' · Payment date: '+($('pay-date').value||'Not set');$('slip-notes').textContent=$('pay-notes').value+Object.entries(c.adjustments||{}).filter(([,v])=>Number(v.minutes)>0).map(([date,v])=>'\n'+date+': additional unpaid break '+v.minutes+' minutes'+(v.reason?' · '+v.reason:'')).join('');$('slip-days').replaceChildren();$('slip-total').replaceChildren();$('slip-total-summary').replaceChildren();$('slip-summary').replaceChildren();try{if($('pay-rate').value==='')throw new Error('Enter this agent’s hourly rate to generate compensation.');const pay=payrollAmounts(c.days,rate,Number($('pay-lunch').value),c.adjustments||{},getPayrollRule());const table=$('slip-days');for(let n=0;n<c.days.length;n++){const day=c.days[n],r=pay.rows[n],tr=document.createElement('tr');const pause=code=>day.pauses.filter(p=>p.campaign==='INS'&&p.code===code).reduce((total,p)=>total+p.seconds,0);for(const value of [day.date,day.calls??'Unavailable',hours(day.totals.talk),hours(day.totals.wait),hours(day.totals.dispo),hours(day.totals.pause),hours(pause('1')),hours(pause('2')),hours(pause('3')),hours(pause('4')),hours(pause('5')),hours(r.recordedLunch),hours(r.lunch),hours(r.deduction),hours(r.manualDeduction),hours(r.seconds)+' ('+(r.seconds/3600).toFixed(4)+')',money(Math.round(rate*100)),r.lastLogout?r.lastLogout.slice(11)+' ET':'Unavailable',r.shiftEnd+' ET',hours(r.finishCallPaid),hours(r.afterCutoff),money(r.cents)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}table.append(tr);}const total=document.createElement('tr'),label=document.createElement('th'),amount=document.createElement('th');label.colSpan=21;label.textContent='Total billable: '+hours(pay.seconds)+' · Total compensation';amount.textContent=money(pay.cents);total.append(label,amount);$('slip-total').append(total);for(const [label,value] of [['Adjusted billable hours',hours(pay.seconds)],['Lunch shortfall deducted',hours(pay.rows.reduce((sum,r)=>sum+r.deduction,0))],['Additional unpaid break',hours(pay.rows.reduce((sum,r)=>sum+r.manualDeduction,0))],['After shift excluded',hours(pay.rows.reduce((sum,r)=>sum+r.afterCutoff,0))],['Hourly rate',money(Math.round(rate*100))],['Total compensation',money(pay.cents)]]){const card=document.createElement('div'),name=document.createElement('span'),strong=document.createElement('strong');name.textContent=label;strong.textContent=value;card.append(name,strong);$('slip-summary').append(card);}$('pay-message').textContent='Payslip ready. Payroll rules are remembered in this browser and included in saved payslips.';$('slip-rule').textContent=payrollRuleDescription();$('pay-print').disabled=false;$('pay-save').disabled=false;renderActivityMetrics(c.data);applyPayslipColumns();}catch(error){$('pay-message').textContent=error.message;}}
for(const id of ['pay-company','pay-rate','pay-currency','pay-date','pay-notes','pay-lunch'])$(id).oninput=()=>{rememberPayroll();renderPayslip();};
$('pay-print').onclick=()=>{if(!cutoffData||$('pay-print').disabled)return;document.body.classList.add('printing-payslip');window.print();};window.addEventListener('afterprint',()=>document.body.classList.remove('printing-payslip'));

$('pay-save').onclick=async()=>{if(!cutoffData||$('pay-save').disabled)return;const snapshot={cutoff:cutoffData,company:$('pay-company').value,rate:$('pay-rate').value,currency:$('pay-currency').value,paymentDate:$('pay-date').value,notes:$('pay-notes').value,lunchMinutes:Number($('pay-lunch').value),rule:getPayrollRule()};$('pay-save').disabled=true;try{const response=await fetch('/api/payslips',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot)});const data=await response.json();if(!response.ok)throw new Error(data.error);$('pay-message').textContent='Payslip saved. Reopen it from Saved payslips without loading activity again.';loadSavedPayslips();}catch(error){$('pay-message').textContent=error.message;}finally{$('pay-save').disabled=false;}};
async function loadSavedPayslips(){const host=$('saved-list');$('saved-message').textContent='Loading saved payslips…';try{const response=await fetch('/api/payslips');const data=await response.json();if(!response.ok)throw new Error(data.error);if(!authorization)return;host.replaceChildren();for(const entry of data.entries){const row=document.createElement('div'),name=document.createElement('span'),load=document.createElement('button'),remove=document.createElement('button');row.className='saved-payslip-row';name.textContent=entry.name+' · '+entry.start+' to '+entry.end+' · '+entry.currency;load.textContent='Load';remove.textContent='Delete';load.onclick=async()=>{try{const response=await fetch('/api/payslips?id='+entry.id),data=await response.json();if(!response.ok)throw new Error(data.error);if(!authorization)return;const s=data.snapshot;setPayrollRule(s.rule);activitySequence++;activityRequest?.abort();cutoffData=s.cutoff;$('activity-agent').value=cutoffData.agent;$('activity-date').value=cutoffData.start;$('activity-end').value=cutoffData.end;for(const [id,value] of [['pay-company',s.company],['pay-rate',s.rate],['pay-currency',s.currency],['pay-date',s.paymentDate],['pay-notes',s.notes],['pay-lunch',s.lunchMinutes??0]])$(id).value=value??'';renderBreakAdjustments();renderPayslip();$('activity-results').classList.add('saved-snapshot');$('activity-results').hidden=false;$('activity-metrics').replaceChildren();$('activity-pauses').replaceChildren();$('activity-statuses').replaceChildren();$('activity-message').textContent='Saved payslip snapshot · '+cutoffData.start+' to '+cutoffData.end+' · Activity was not refetched.';}catch(error){$('saved-message').textContent=error.message;}};remove.onclick=async()=>{if(!confirm('Delete this saved payslip from the list?'))return;try{const response=await fetch('/api/payslips?id='+entry.id,{method:'DELETE'});if(!response.ok)throw new Error((await response.json()).error);loadSavedPayslips();}catch(error){$('saved-message').textContent=error.message;}};row.append(name,load,remove);host.append(row);}$('saved-message').textContent=data.entries.length+' saved payslips';}catch(error){$('saved-message').textContent=error.message;}}
$('load-saved-payslips').onclick=loadSavedPayslips;

function renderBreakAdjustments(){const host=$('break-adjustments');host.replaceChildren();if(!cutoffData)return;cutoffData.adjustments ||= {};for(const day of cutoffData.days){const row=document.createElement('div'),label=document.createElement('label'),input=document.createElement('input'),reason=document.createElement('input');row.className='break-adjustment-row';label.textContent=day.date+' · Additional unpaid break (minutes)';input.type='number';input.min='0';input.max='1440';input.step='1';input.value=cutoffData.adjustments[day.date]?.minutes||0;input.setAttribute('aria-label',day.date+' unpaid break minutes');reason.maxLength=200;reason.placeholder='Reason, e.g. forgot to log out';reason.setAttribute('aria-label',day.date+' adjustment reason');reason.value=cutoffData.adjustments[day.date]?.reason||'';const update=()=>{cutoffData.adjustments[day.date]={minutes:input.value,reason:reason.value};renderPayslip();};input.oninput=update;reason.oninput=update;label.append(input);row.append(label,reason);host.append(row);}}

function renderActivityMetrics(data){
 if(!data)return;const host=$('activity-metrics');host.replaceChildren();
 const t=data.totals;let billable=t?hours(t.talk+t.wait+t.dispo):'Unavailable';
 try{if(payrollPage&&cutoffData)billable=hours(payrollAmounts(cutoffData.days,0,Number($('pay-lunch').value),cutoffData.adjustments||{},getPayrollRule()).seconds);}catch{billable='Unavailable';}
 const pause=code=>t?hours(data.pauses.filter(p=>p.campaign==='INS'&&p.code===code).reduce((n,p)=>n+p.seconds,0)):'Unavailable';
 const groups=[['Totals','overview',[['Total calls',data.calls??'Unavailable'],['Total login sessions',hours(data.sessionSeconds)],['Total billable hours',billable]]],['Billable','billable',[['Activity talk',hours(t?.talk)],['Waiting',hours(t?.wait)],['Wrap-up',hours(t?.dispo)]]],['Non-billable','nonbillable',[['All pauses',hours(t?.pause)],['Break',pause('1')],['Restroom',pause('4')],['Recorded lunch',pause('6')]]],['Reference totals','reference',[['Call time',hours(data.callSeconds)],['Dead time',hours(t?.dead)]]]];
 const rule=getPayrollRule();const timed=[['talk','Activity talk'],['wait','Waiting'],['dispo','Wrap-up']];groups[1][2]=timed.filter(([k])=>rule[k]).map(([k,label])=>[label,hours(t?.[k])]);groups[2][2].push(...timed.filter(([k])=>!rule[k]).map(([k,label])=>[label+' (excluded)',hours(t?.[k])]));for(const [title,theme,values]of groups){const section=document.createElement('section');section.className='activity-metric-group '+theme;const heading=document.createElement('h3');heading.textContent=title;const grid=document.createElement('div');grid.className='activity-metrics';for(const[label,value]of values){const card=document.createElement('div'),name=document.createElement('span'),number=document.createElement('strong');name.textContent=label;number.textContent=value;card.append(name,number);grid.append(card);}section.append(heading,grid);host.append(section);}
}

const PAYSLIP_COLUMNS=['Day','Calls','Talk','Wait','Wrap-up','Pauses','Recorded break','Transfer','Training','Restroom','Call Back','Recorded lunch','Payroll lunch','Lunch deduction','Additional unpaid break','Billable hours','Rate / hour','Last logout (ET)','Shift end (ET)','Finish-call extension','After shift excluded','Compensation'];
const PAYSLIP_OPTIONAL=new Set([6,7,10,12,14]);
let payslipColumnOverrides={};
const DEFAULT_PAYSLIP_ORDER=[15,16,21,...PAYSLIP_COLUMNS.map((_,i)=>i).filter(i=>![15,16,21].includes(i))];
let payslipColumnOrder=[...DEFAULT_PAYSLIP_ORDER],draggedPayslipColumn=null;
let payrollLayoutLoad=null,payrollLayoutTimer=null,payrollLayoutRevision=0,payrollLayoutWrites=Promise.resolve();
async function loadPayrollLayout(){if(payrollLayoutLoad)return payrollLayoutLoad;const revision=payrollLayoutRevision;payrollLayoutLoad=(async()=>{try{const response=await fetch('/api/payslips?preferences=layout');const data=await response.json();if(!response.ok)throw Error(data.error||'Could not load layout.');if(data.layout&&revision===payrollLayoutRevision){payslipColumnOrder=data.layout.order;payslipColumnOverrides=data.layout.overrides;$('pay-view').value=data.layout.view;$('pay-hide-zero').checked=data.layout.hideZero;applyPayslipColumns();$('pay-column-status').textContent='Layout loaded from your account.';}}catch(error){$('pay-column-status').textContent='Account layout unavailable. '+error.message;}})();return payrollLayoutLoad;}
function savePayrollLayout(){if(!payrollPage||!authorization)return;payrollLayoutRevision++;clearTimeout(payrollLayoutTimer);$('pay-column-status').textContent='Saving layout to your account…';payrollLayoutTimer=setTimeout(()=>{const layout={order:[...payslipColumnOrder],overrides:{...payslipColumnOverrides},view:$('pay-view').value,hideZero:$('pay-hide-zero').checked},revision=payrollLayoutRevision;payrollLayoutWrites=payrollLayoutWrites.catch(()=>{}).then(async()=>{await loadPayrollLayout();if(!authorization||revision!==payrollLayoutRevision)return;try{const response=await fetch('/api/payslips?preferences=layout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(layout)});const data=await response.json();if(!response.ok)throw Error(data.error||'Could not save layout.');if(revision===payrollLayoutRevision)$('pay-column-status').textContent='Layout saved to your account. Available on other PCs.';}catch(error){$('pay-column-status').textContent='Layout was not saved to your account. '+error.message;}});},400);}
try{const saved=JSON.parse(localStorage.getItem('qa-payslip-column-order'));if(Array.isArray(saved)&&saved.length===PAYSLIP_COLUMNS.length&&new Set(saved).size===saved.length&&saved.every(i=>Number.isInteger(i)&&i>=0&&i<PAYSLIP_COLUMNS.length))payslipColumnOrder=saved;}catch{}
function movePayslipColumn(source,target){if(source===target)return;const from=payslipColumnOrder.indexOf(source),to=payslipColumnOrder.indexOf(target);if(from<0||to<0)return;payslipColumnOrder.splice(from,1);payslipColumnOrder.splice(to,0,source);try{localStorage.setItem('qa-payslip-column-order',JSON.stringify(payslipColumnOrder));}catch{}applyPayslipColumns();savePayrollLayout();}
function applyPayslipColumns(){
 const table=$('payslip').querySelector('table'),rows=[...$('slip-days').rows],compact=$('pay-view').value==='professional';
 table.classList.toggle('professional-table',compact);let visible=0;
 for(const row of [table.tHead.rows[0],...rows]){for(const [i,cell]of [...row.cells].entries())if(!cell.dataset.column)cell.dataset.column=String(i);}
 PAYSLIP_COLUMNS.forEach((name,i)=>{const cellFor=row=>[...row.cells].find(cell=>Number(cell.dataset.column)===i);const zero=i>1&&i<15&&rows.length>0&&rows.every(row=>/^0:00:00$/.test(cellFor(row)?.textContent||''));const show=payslipColumnOverrides[i]??((!compact||!PAYSLIP_OPTIONAL.has(i))&&(!$('pay-hide-zero').checked||!zero));for(const row of [table.tHead.rows[0],...rows]){const cell=cellFor(row);if(cell)cell.hidden=!show;}if(show)visible++;const input=$('pay-columns').querySelector('[data-column="'+i+'"]');if(input)input.checked=show;});
 for(const row of [table.tHead.rows[0],...rows]){const cells=new Map([...row.cells].map(cell=>[Number(cell.dataset.column),cell]));for(const i of payslipColumnOrder)row.append(cells.get(i));}
 const options=$('pay-columns');for(const i of payslipColumnOrder)options.append(options.querySelector('[data-column-option="'+i+'"]'));
 const total=$('slip-total').rows[0];if(total){const label=total.cells[0],amount=total.cells[1];if(amount){const content=document.createElement('div'),hoursLabel=document.createElement('span'),payLabel=document.createElement('span'),payAmount=document.createElement('strong');content.className='payslip-total-content';hoursLabel.textContent=label.textContent.replace(' · Total compensation','');payLabel.className='payslip-total-pay';payLabel.append(document.createTextNode('Total compensation '));payAmount.textContent=amount.textContent;payLabel.append(payAmount);content.append(hoursLabel,payLabel);label.replaceChildren(content);amount.remove();}label.colSpan=Math.max(1,visible);$('slip-total-summary').replaceChildren(label.firstElementChild.cloneNode(true));}
}
for(let i=0;i<PAYSLIP_COLUMNS.length;i++){const label=document.createElement('label'),input=document.createElement('input');label.dataset.columnOption=i;input.type='checkbox';input.dataset.column=i;input.disabled=[0,15,21].includes(i);input.onchange=()=>{payslipColumnOverrides[i]=input.checked;applyPayslipColumns();savePayrollLayout();};label.append(input,document.createTextNode(PAYSLIP_COLUMNS[i]));for(const [direction,text]of [[-1,'←'],[1,'→']]){const button=document.createElement('button');button.type='button';button.className='column-move';button.textContent=text;button.setAttribute('aria-label','Move '+PAYSLIP_COLUMNS[i]+(direction<0?' left':' right'));button.onclick=()=>{const at=payslipColumnOrder.indexOf(i),target=payslipColumnOrder[at+direction];if(target!==undefined)movePayslipColumn(i,target);};label.append(button);}$('pay-columns').append(label);}
for(const [i,header]of [...$('payslip').querySelector('table').tHead.rows[0].cells].entries()){header.dataset.column=i;header.draggable=true;header.tabIndex=0;header.title='Drag to reorder, or use Alt + Left/Right';header.setAttribute('aria-label',PAYSLIP_COLUMNS[i]+'. Drag to reorder or press Alt Left or Right.');header.addEventListener('dragstart',event=>{draggedPayslipColumn=i;event.dataTransfer.setData('text/plain',String(i));event.dataTransfer.effectAllowed='move';});header.addEventListener('dragover',event=>{if(draggedPayslipColumn!==null){event.preventDefault();event.dataTransfer.dropEffect='move';}});header.addEventListener('drop',event=>{event.preventDefault();if(draggedPayslipColumn!==null)movePayslipColumn(draggedPayslipColumn,i);draggedPayslipColumn=null;});header.addEventListener('dragend',()=>{draggedPayslipColumn=null;});header.addEventListener('keydown',event=>{if(event.altKey&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const at=payslipColumnOrder.indexOf(i),target=payslipColumnOrder[at+(event.key==='ArrowLeft'?-1:1)];if(target!==undefined){movePayslipColumn(i,target);header.focus();}}});}
$('pay-reset-columns').onclick=()=>{payslipColumnOrder=[...DEFAULT_PAYSLIP_ORDER];try{localStorage.removeItem('qa-payslip-column-order');}catch{}applyPayslipColumns();savePayrollLayout();};
$('pay-view').onchange=()=>{payslipColumnOverrides={};$('pay-hide-zero').checked=$('pay-view').value==='professional';applyPayslipColumns();savePayrollLayout();};
$('pay-hide-zero').onchange=()=>{payslipColumnOverrides={};applyPayslipColumns();savePayrollLayout();};

function getPayrollRule(){return {...Object.fromEntries(['talk','wait','dispo','lunch','manual'].map(k=>[k,$('rule-'+k).checked])),cutoff:$('rule-cutoff').checked,finishCall:$('rule-finish-call').checked,shiftEnd:$('pay-shift-end').value,shiftEnds:{...payrollShiftEnds}};}
function setPayrollRule(rule){for(const k of ['talk','wait','dispo','lunch','manual'])$('rule-'+k).checked=k==='lunch'?(rule?rule.lunch!==false:false):rule?.[k]!==false;$('rule-cutoff').checked=rule?rule.cutoff===true:true;$('rule-finish-call').checked=rule?rule.finishCall===true:true;$('pay-shift-end').value=rule?.shiftEnd||'18:30';payrollShiftEnds={...(rule?.shiftEnds||{})};renderPayrollSchedule();}
function payrollRuleDescription(){const r=getPayrollRule();return 'Paid time: '+[['talk','Talk'],['wait','Waiting'],['dispo','Wrap-up']].filter(([k])=>r[k]).map(([,v])=>v).join(' + ')+'. Deductions: '+([r.lunch?'Lunch shortfall':null,r.manual?'Additional unpaid break':null].filter(Boolean).join(' + ')||'None')+(r.cutoff?' · Eastern shift end '+r.shiftEnd+' (date overrides apply)'+(r.finishCall?'; finish current call, no late wrap-up':'')+'':'')+'. Recorded pauses remain excluded. Daily compensation rounds to two decimals.';}
for(const k of ['talk','wait','dispo','lunch','manual','cutoff','finish-call'])$('rule-'+k).onchange=()=>{rememberPayroll();renderPayslip();};

$('copy-recording').onclick=async()=>{const url=playing?recordingLink(playing):'';const status=$('copy-recording-status');if(!url){status.textContent='Recording address unavailable.';return;}try{await navigator.clipboard.writeText(url);status.textContent='Address copied';}catch{status.replaceChildren(document.createTextNode('Copy this address: '));const input=document.createElement('input');input.value=url;input.readOnly=true;input.setAttribute('aria-label','Recording address');status.append(input);input.select();}};

$('open-live').href=viewerBase+'live';
let liveTimer=null,liveRequest=null,liveUsername='',liveBusy=false,liveGeneration=0;
function stopLive(){disconnectSupervisorPhone();localMonitor=null;try{if(liveUsername)localStorage.removeItem('qa-monitor-lock:'+liveUsername);}catch{}clearTimeout(liveTimer);liveTimer=null;liveGeneration++;liveRequest?.abort();}
async function startLive(){const response=await fetch('/api/session');if(!response.ok||!authorization)return;const data=await response.json();liveUsername=data.username;try{if(sessionStorage.getItem('qa-monitor-reload:'+liveUsername)==='1'){localStorage.removeItem('qa-monitor-lock:'+liveUsername);sessionStorage.removeItem('qa-monitor-reload:'+liveUsername);}localMonitor=JSON.parse(localStorage.getItem('qa-monitor-lock:'+liveUsername)||'null');$('confirm-disconnected').hidden=true;}catch{}try{$('live-phone').value=localStorage.getItem('qa-live-phone:'+liveUsername)||'';}catch{}loadLive();if(!$('live-phone').value.trim()){const username=liveUsername,generation=liveGeneration;try{const response=await fetch('/api/webphone');const config=await readLiveResponse(response);if(response.ok&&authorization&&generation===liveGeneration&&username===liveUsername&&!$('live-phone').value.trim()&&/^\d{1,20}$/.test(config.phone||'')){$('live-phone').value=config.phone;try{localStorage.setItem('qa-live-phone:'+username,config.phone);}catch{}}}catch{}}}
function scheduleLive(){clearTimeout(liveTimer);const seconds=Number($('live-interval').value);if(livePage&&authorization&&seconds>0)liveTimer=setTimeout(()=>{if(document.hidden)scheduleLive();else loadLive();},seconds*1000);}
async function loadLive(){if(!authorization||liveRequest||liveBusy)return;clearTimeout(liveTimer);const controller=new AbortController(),generation=liveGeneration;liveRequest=controller;$('live-refresh').disabled=true;try{const response=await fetch('/api/live?'+new URLSearchParams({phone:$('live-phone').value.trim()}),{signal:controller.signal});const data=await readLiveResponse(response);if(!response.ok)throw Error(data.error);if(generation!==liveGeneration||!authorization)return;const host=$('live-rows');host.replaceChildren();for(const agent of data.agents){const row=document.createElement('tr');row.className='live-tone-'+liveAgentTone(agent);for(const value of [agent.name,agent.station,agent.campaign,agent.status,agent.pause||'—',agent.time,agent.calls,agent.transfers??'—',agent.latency||'—',agent.customer||'—',(agent.monitorRequests||[]).map(r=>r.supervisor+' · '+(r.mode==='WHISPER'?'Whisper':'Listen')+' · Ext '+r.phone+' · '+new Date(r.acceptedAt).toLocaleString()).join('\n')||'—']){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}const actions=document.createElement('td');for(const [mode,label]of [['MONITOR','Listen'],['WHISPER','Whisper']]){const button=document.createElement('button');button.type='button';button.textContent=label;button.setAttribute('aria-label',label+' to '+agent.name);button.disabled=!!localMonitor;button.onclick=()=>monitorAgent(agent,mode);actions.append(button);}if(localMonitor?.session===agent.session){const stop=document.createElement('button');stop.type='button';stop.className='live-stop';stop.textContent='Stop';stop.setAttribute('aria-label','Stop monitoring '+agent.name);stop.onclick=stopSupervisorMonitoring;actions.append(stop);}row.append(actions);host.append(row);}$('live-status').textContent=data.agents.length+' live agents · Updated '+new Date(data.updatedAt).toLocaleTimeString()+(data.qaWarning?' · '+data.qaWarning:data.qaUpdatedAt?' · QA snapshot '+new Date(data.qaUpdatedAt).toLocaleTimeString():'');}catch(error){if(error.name!=='AbortError')$('live-status').textContent=error.message+' Last successful list retained.';}finally{if(liveRequest===controller)liveRequest=null;$('live-refresh').disabled=false;scheduleLive();}}
async function monitorAgent(agent,mode){if(liveBusy||!authorization)return;if(localMonitor){$('live-command-status').textContent='Select Stop to close the current browser phone before monitoring another agent.';return;}const phone=$('live-phone').value.trim();if(!/^\d{1,20}$/.test(phone)){$('live-command-status').textContent='Enter your assigned supervisor extension first.';$('live-phone').focus();return;}const commandGeneration=liveGeneration;liveBusy=true;liveRequest?.abort();clearTimeout(liveTimer);for(const button of $('live-rows').querySelectorAll('button'))button.disabled=true;$('live-command-status').textContent='Requesting '+(mode==='WHISPER'?'Whisper':'Listen')+' for '+agent.name+'…';try{if(!$('supervisor-webphone').children.length){await connectSupervisorPhone();const frame=$('supervisor-webphone').children[0];if(!frame)throw Error('Browser phone could not open.');$('live-command-status').textContent='Starting your browser phone…';await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{frame.onload=null;reject(Error('Browser phone did not finish loading. Show phone and check its connection.'));},20000);frame.onload=()=>{clearTimeout(timer);frame.onload=null;setTimeout(resolve,3000);};});}if(!authorization||commandGeneration!==liveGeneration)return;const response=await fetch('/api/monitor',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({session:agent.session,phone,mode})});const data=await readLiveResponse(response);if(!response.ok)throw Error(data.error);if(authorization&&commandGeneration===liveGeneration){localMonitor={session:agent.session,mode};try{localStorage.setItem('qa-monitor-lock:'+liveUsername,JSON.stringify(localMonitor));}catch{}$('confirm-disconnected').hidden=true;$('live-command-status').textContent=data.message;}}catch(error){if(authorization&&commandGeneration===liveGeneration)$('live-command-status').textContent=error.message||'Monitoring was not confirmed. Check your phone before trying again.';}finally{liveBusy=false;for(const button of $('live-rows').querySelectorAll('button'))button.disabled=!!localMonitor&&!button.classList.contains('live-stop');if(authorization&&commandGeneration===liveGeneration)loadLive();else scheduleLive();}}
$('live-phone').onchange=()=>{try{if(liveUsername)localStorage.setItem('qa-live-phone:'+liveUsername,$('live-phone').value.trim());}catch{}};$('live-refresh').onclick=loadLive;$('live-interval').onchange=scheduleLive;

async function readLiveResponse(response){if(!(response.headers.get('Content-Type')||'').includes('application/json'))throw Error('The live service returned HTTP '+response.status+'. Please try again shortly.');return response.json();}

function resetAgentLanding(){if(teamPage||livePage||activityPage||reportPage)return;$('agent').value='';$('agent-picker').value='';loadedContext=null;$('agent-name').textContent='Agent recordings';const url=new URL(location.href);url.searchParams.delete('u');history.replaceState(null,'',url);for(const [id,path]of [['open-activity','activity'],['open-reports','reports'],['open-team','team']])$(id).href=viewerBase+path+'?'+new URLSearchParams({q:$('date').value});}

function setAccountProfile(username){const name=typeof username==='string'?username:'';$('account-greeting').textContent=name?accountGreeting(name):'Welcome';$('account-username').textContent=name;$('account-avatar').textContent=name.slice(0,2).toUpperCase()||'U';$('account-menu-avatar').textContent=name.slice(0,2).toUpperCase()||'U';if(name)loadProfileSettings(name);else $('app-brand').textContent='AIG / Monitoring System';}
$('nav-recordings').href=viewerBase;
const currentNav=teamPage?'open-team':livePage?'open-live':payrollPage?'open-payroll':activityPage?'open-activity':reportPage?'open-reports':'nav-recordings';$(currentNav).setAttribute('aria-current','page');
document.addEventListener('click',event=>{if(!$('account-menu').contains(event.target))$('account-menu').open=false;});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('account-menu').open){$('account-menu').open=false;$('account-menu').querySelector('summary').focus();}});

let supervisorPhoneGeneration=0,supervisorPhoneRequest=null,localMonitor=null;
function disconnectSupervisorPhone(){$('live-command-status').textContent='Monitoring request cleared. This page’s browser phone is closed; monitoring started in another phone or tab must be stopped there.';supervisorPhoneGeneration++;supervisorPhoneRequest?.abort();supervisorPhoneRequest=null;const host=$('supervisor-webphone');host.replaceChildren();host.hidden=true;$('show-webphone').hidden=true;$('disconnect-webphone').hidden=true;$('connect-webphone').disabled=false;$('webphone-status').textContent='Browser phone disconnected from this page. Monitoring through another tab or external phone must be ended there.';}
async function connectSupervisorPhone(){if(!authorization||supervisorPhoneRequest)return;const phone=$('live-phone').value.trim();if(!/^\d{1,20}$/.test(phone)){$('webphone-status').textContent='Enter your assigned supervisor extension first.';return;}disconnectSupervisorPhone();const generation=supervisorPhoneGeneration,request=new AbortController();supervisorPhoneRequest=request;$('connect-webphone').disabled=true;$('webphone-status').textContent='Loading your configured supervisor webphone…';try{const response=await fetch('/api/webphone',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone}),signal:request.signal});const data=await readLiveResponse(response);if(!response.ok)throw Error(data.error);if(generation!==supervisorPhoneGeneration||!authorization)return;const url=new URL(data.url);if(url.origin!=='https://crm.usa-benefitsgroup.com'||url.pathname!=='/phone/viciphone.php')throw Error('Unsupported supervisor phone.');const frame=document.createElement('iframe');frame.title='Supervisor browser phone';frame.src=url.href;frame.allow='microphone https://crm.usa-benefitsgroup.com; autoplay https://crm.usa-benefitsgroup.com';frame.referrerPolicy='no-referrer';$('supervisor-webphone').append(frame);$('supervisor-webphone').hidden=false;$('supervisor-webphone').classList.add('phone-collapsed');$('show-webphone').hidden=false;$('show-webphone').textContent='Show phone';$('disconnect-webphone').hidden=false;$('webphone-status').textContent='Browser phone opened in the background. Show phone for microphone permission or phone controls. Select Stop before monitoring another agent. If audio remains after Stop, use Reload page.';}catch(error){if(error.name!=='AbortError'&&generation===supervisorPhoneGeneration)$('webphone-status').textContent=error.message||'Could not open the supervisor phone.';}finally{if(supervisorPhoneRequest===request){supervisorPhoneRequest=null;$('connect-webphone').disabled=false;}}}
$('connect-webphone').onclick=connectSupervisorPhone;$('disconnect-webphone').onclick=stopSupervisorMonitoring;$('live-phone').addEventListener('input',()=>{if(!$('supervisor-webphone').hidden)disconnectSupervisorPhone();});

function liveAgentTone(agent){const status=String(agent.status||'').toUpperCase(),parts=String(agent.time||'').split(':').map(Number),seconds=parts.length===3?parts[0]*3600+parts[1]*60+parts[2]:parts.length===2?parts[0]*60+parts[1]:0;if(status==='DEAD')return 'dead';if(status==='CHAT'||status==='CHATTING')return 'chat';if(status==='EMAIL')return 'email';if(status==='READY')return seconds>300?'ready-long':seconds>60?'ready-medium':'ready';if(status==='INCALL')return seconds>300?'call-long':seconds>60?'call-medium':'call';if(status==='PAUSED'||status==='PAUSE')return seconds>900?'pause-long':seconds>600?'pause-medium':seconds>300?'pause-five':seconds>60?'pause-minute':'pause';if(status==='3WAY')return 'threeway';return 'other';}


async function stopSupervisorMonitoring(){if(liveBusy)return;const frame=$('supervisor-webphone').children[0];if(!frame){localMonitor=null;try{localStorage.removeItem('qa-monitor-lock:'+liveUsername);}catch{}$('confirm-disconnected').hidden=true;$('live-command-status').textContent='Old monitoring selection cleared. No browser phone is open on this page. Calls in another tab or phone must be ended there.';loadLive();return;}const generation=liveGeneration;liveBusy=true;clearTimeout(liveTimer);$('disconnect-webphone').disabled=true;$('live-command-status').textContent='Closing the browser phone without reloading the agent list…';try{await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{frame.onload=null;reject(Error('Phone reset did not finish. Use Reload page as the fallback.'));},10000);frame.onload=()=>{clearTimeout(timer);frame.onload=null;resolve();};frame.src='about:blank';});if(generation!==liveGeneration||!authorization)return;disconnectSupervisorPhone();localMonitor=null;try{localStorage.removeItem('qa-monitor-lock:'+liveUsername);}catch{}$('live-command-status').textContent='Browser phone closed. Listen or Whisper will open it again. If you still hear audio, use Reload page before monitoring another agent.';}catch(error){if(generation===liveGeneration&&authorization)$('live-command-status').textContent=error.message;}finally{liveBusy=false;$('disconnect-webphone').disabled=false;if(generation===liveGeneration&&authorization)loadLive();}}
$('show-webphone').onclick=()=>{const collapsed=$('supervisor-webphone').classList.toggle('phone-collapsed');$('show-webphone').textContent=collapsed?'Show phone':'Hide phone';};
$('confirm-disconnected').onclick=()=>{if(liveBusy)return;if(!confirm('Have you hung up your supervisor monitoring call? Confirm only after the call has ended.'))return;localMonitor=null;try{localStorage.removeItem('qa-monitor-lock:'+liveUsername);}catch{}$('confirm-disconnected').hidden=true;$('live-command-status').textContent='Disconnection confirmed by you. Listen and Whisper are unlocked.';loadLive();};

$('reload-live-page').onclick=()=>{if(liveBusy){$('live-command-status').textContent='Wait for the monitoring request to finish before reloading.';return;}location.reload();};

$('unsure-reason').onchange=()=>{const notes=setUnsureReason($('notes-text').value,$('unsure-reason').value);if(notes.length>4000){$('notes-status').textContent='Shorten the note to add this reason.';syncVerdict();return;}$('notes-text').value=notes;syncVerdict();};

function renderPayrollSchedule(){const host=$('pay-shift-dates');host.replaceChildren();if(!cutoffData)return;for(const day of cutoffData.days){const label=document.createElement('label');label.textContent=day.date+' ET';const input=document.createElement('input');input.type='time';input.value=payrollShiftEnds[day.date]||'';input.setAttribute('aria-label','Shift end for '+day.date);input.onchange=()=>{if(input.value)payrollShiftEnds[day.date]=input.value;else delete payrollShiftEnds[day.date];rememberPayroll();renderPayslip();};label.append(input);host.append(label);}}
$('pay-shift-end').onchange=()=>{rememberPayroll();renderPayslip();};
if(payrollPage){$('activity-page').querySelector('h1').textContent='Payroll';$('activity-page').querySelector('.eyebrow').textContent='HOURS AND PAYSLIPS';$('activity-load').textContent='Load payroll activity';}else if(activityPage){const link=document.createElement('a');link.href=$('open-payroll').href;link.textContent='Open Payroll for payslips';$('activity-form').after(link);}

if(payrollPage){const audit=document.createElement('details');audit.className='payroll-audit';const summary=document.createElement('summary');summary.textContent='Activity breakdown';audit.append(summary);for(let node=$('activity-metrics');node;){const next=node.nextSibling;audit.append(node);node=next;}$('activity-results').append(audit);$('activity-date').parentElement.firstChild.textContent='Pay period start';$('activity-end').parentElement.firstChild.textContent='Pay period end';}

async function loadProfileSettings(username){try{const configResponse=await fetch('/api/login-config'),config=await configResponse.json();if(!configResponse.ok)throw Error(config.error||'Configuration unavailable.');if($('account-username').textContent!==username)return;vicidialOrigin=config.vicidialOrigin||'https://myvici.info';$('profile-vicidial-origin').value=vicidialOrigin;let appName=config.appName||'AIG / Monitoring System';const response=await fetch('/api/payslips?preferences=profile'),data=await response.json();if($('account-username').textContent!==username)return;if(!response.ok)throw Error(data.error||'Profile unavailable.');appName=data.profile?.appName||appName;$('app-brand').textContent=appName;$('profile-app-name').value=appName;$('profile-settings-status').textContent='Your app name is saved to your account across PCs.';}catch(error){$('profile-settings-status').textContent=error.message;}}
$('open-profile-settings').onclick=()=>{$('account-menu').open=false;$('profile-settings').showModal();};
$('close-profile-settings').onclick=()=>$('profile-settings').close();
$('profile-settings-form').onsubmit=async event=>{event.preventDefault();const username=$('account-username').textContent;$('profile-settings-status').textContent='Saving…';try{const response=await fetch('/api/payslips?preferences=profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({appName:$('profile-app-name').value.trim()})}),data=await response.json();if(!response.ok)throw Error(data.error||'Could not save profile.');if($('account-username').textContent!==username)return;$('app-brand').textContent=data.profile.appName;$('profile-settings-status').textContent='Profile saved to your account.';}catch(error){$('profile-settings-status').textContent=error.message;}};

function accountGreeting(username){const hour=new Date().getHours();return (hour<12?'Good morning':hour<18?'Good afternoon':'Good evening')+', '+username;}
setInterval(()=>{const username=$('account-username').textContent;if(username)$('account-greeting').textContent=accountGreeting(username);},60000);
